input.raw_json:
{
  "properties": {
    "hs_timestamp": "{{ CTX.hs_timestamp }}",
    "hs_meeting_title": "{{ CTX.hs_meeting_title }}",
    "hs_meeting_body": {{ CTX.hs_meeting_body | default('""', true) | tojson }},
    "hs_meeting_outcome": "{{ CTX.hs_meeting_outcome }}",
    "hs_meeting_start_time": "{{ CTX.meeting_start_time }}",
    "hs_meeting_end_time": "{{ CTX.meeting_end_time }}",
    "hs_activity_type": "{{ CTX.hs_activity_type }}"
  },
  "associations": [
    {
      "to": {
        "id": {{ CTX.contact_id }}
      },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 200
        }
      ]
    },
    {
      "to": {
        "id": {{ CTX.company_id }}
      },
      "types": [
        {
          "associationCategory": "HUBSPOT_DEFINED",
          "associationTypeId": 188
        }
      ]
    }
    {% if CTX.training_id %}
    ,{
      "to": {
        "id": {{ CTX.training_id }}
      },
      "types": [
        {
          "associationCategory": "USER_DEFINED",
          "associationTypeId": 8
        }
      ]
    }
    {% endif %}
  ]
}

